def group_by_key(data: list[dict], key: str) -> dict:
    """Group a list of dictionaries by the value of a given key.

    Args:
        data: List of dictionaries to group.
        key: The key to group by.

    Returns:
        A dictionary where keys are unique values of the specified key and values are lists of dictionaries.

    Example:
        >>> data = [{'name': 'Alice', 'age': 30}, {'name': 'Bob', 'age': 30}, {'name': 'Charlie', 'age': 25}]
        >>> group_by_key(data, 'age')
        {30: [{'name': 'Alice', 'age': 30}, {'name': 'Bob', 'age': 30}], 25: [{'name': 'Charlie', 'age': 25}]}
    """
    if not data:
        return {}
    result = {}
    for item in data:
        if key not in item:
            raise ValueError(f"Key '{key}' not found in dictionary {item}")
        k = item[key]
        if k not in result:
            result[k] = []
        result[k].append(item)
    return result
